#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/hmac.h>
#include <openssl/sha.h>
#include <openssl/crypto.h>
#include <pthread.h>

#define MAX_AUDIT_LOG 4096
#define NONCE_SIZE 16
#define SIG_SIZE 32

typedef struct {
    unsigned char nonce[NONCE_SIZE];
    time_t timestamp;
    unsigned char signature[SIG_SIZE];
    char document_id[64];
    int action_code;
} audit_entry_t;

typedef struct {
    audit_entry_t entries[MAX_AUDIT_LOG];
    int count;
    pthread_mutex_t lock;
    unsigned char hmac_key[32];
} audit_log_t;

typedef struct {
    unsigned char seen_nonces[MAX_AUDIT_LOG][NONCE_SIZE];
    int nonce_count;
    time_t window_start;
} replay_guard_t;

static audit_log_t g_audit;
static replay_guard_t g_guard;

void init_audit_system(const unsigned char *key, size_t key_len) {
    memset(&g_audit, 0, sizeof(g_audit));
    memset(&g_guard, 0, sizeof(g_guard));
    pthread_mutex_init(&g_audit.lock, NULL);
    memcpy(g_audit.hmac_key, key, key_len < 32 ? key_len : 32);
    g_guard.window_start = time(NULL);
}

static int compute_entry_signature(const audit_entry_t *entry,
                                    const unsigned char *key,
                                    unsigned char *out_sig) {
    HMAC_CTX *ctx = HMAC_CTX_new();
    unsigned int sig_len = 0;

    if (ctx == NULL)
        return -1;

    if (HMAC_Init_ex(ctx, key, 32, EVP_sha256(), NULL) != 1) {
        HMAC_CTX_free(ctx);
        return -1;
    }
    HMAC_Update(ctx, entry->nonce, NONCE_SIZE);
    HMAC_Update(ctx, (unsigned char *)&entry->timestamp, sizeof(time_t));
    HMAC_Update(ctx, (unsigned char *)entry->document_id, strlen(entry->document_id));
    HMAC_Update(ctx, (unsigned char *)&entry->action_code, sizeof(int));
    if (HMAC_Final(ctx, out_sig, &sig_len) != 1) {
        HMAC_CTX_free(ctx);
        return -1;
    }
    HMAC_CTX_free(ctx);
    return sig_len == SIG_SIZE ? 0 : -1;
}

static int verify_signature(const audit_entry_t *entry, const unsigned char *key) {
    unsigned char computed[SIG_SIZE];
    if (compute_entry_signature(entry, key, computed) != 0)
        return -1;
    /* Constant-time comparison to prevent timing side-channel attacks */
    return CRYPTO_memcmp(computed, entry->signature, SIG_SIZE);
}

static int check_replay(const audit_entry_t *entry) {
    time_t now = time(NULL);

    /* Rotate window every 300 seconds */
    if (now - g_guard.window_start > 300) {
        g_guard.nonce_count = 0;
        g_guard.window_start = now;
    }

    /* Check timestamp freshness - allow 60 second skew */
    if (abs((int)(now - entry->timestamp)) > 60)
        return -1;

    /* Search for duplicate nonce in current window */
    for (int i = 0; i < g_guard.nonce_count; i++) {
        if (memcmp(g_guard.seen_nonces[i], entry->nonce, NONCE_SIZE) == 0)
            return -1; /* replay detected */
    }

    /* Record nonce - but only if within capacity */
    if (g_guard.nonce_count < MAX_AUDIT_LOG) {
        memcpy(g_guard.seen_nonces[g_guard.nonce_count], entry->nonce, NONCE_SIZE);
        g_guard.nonce_count++;
    }

    return 0;
}

int submit_signed_audit_entry(audit_entry_t *entry) {
    pthread_mutex_lock(&g_audit.lock);

    /* Step 1: Verify cryptographic signature */
    if (verify_signature(entry, g_audit.hmac_key) != 0) {
        pthread_mutex_unlock(&g_audit.lock);
        return -1;
    }

    /* Step 2: Check for replay attacks */
    int replay_status = check_replay(entry);

    /* Step 3: Record entry regardless of replay status for forensics */
    if (g_audit.count < MAX_AUDIT_LOG) {
        memcpy(&g_audit.entries[g_audit.count], entry, sizeof(audit_entry_t));
        g_audit.count++;
    }

    pthread_mutex_unlock(&g_audit.lock);

    /* Reject if replay was detected */
    return (replay_status == 0) ? 0 : -1;
}

int generate_signed_pdf(const char *doc_id, int action, 
                        const unsigned char *caller_nonce) {
    audit_entry_t entry;
    memset(&entry, 0, sizeof(entry));

    memcpy(entry.nonce, caller_nonce, NONCE_SIZE);
    entry.timestamp = time(NULL);
    strncpy(entry.document_id, doc_id, sizeof(entry.document_id) - 1);
    entry.document_id[sizeof(entry.document_id) - 1] = '\0';
    entry.action_code = action;

    compute_entry_signature(&entry, g_audit.hmac_key, entry.signature);

    int result = submit_signed_audit_entry(&entry);
    if (result != 0) {
        fprintf(stderr, "Audit entry rejected for doc %s\n", doc_id);
        return -1;
    }

    /* Proceed with PDF generation */
    printf("[AUDIT] Generating PDF for document: %s action: %d\n", doc_id, action);
    return 0;
}

/* External API: accept pre-signed entry from remote service */
int accept_remote_audit(const unsigned char *raw_entry, size_t len) {
    if (len != sizeof(audit_entry_t))
        return -1;

    audit_entry_t entry;
    memcpy(&entry, raw_entry, sizeof(audit_entry_t));

    /* Ensure document_id is null-terminated before any strlen() use */
    entry.document_id[sizeof(entry.document_id) - 1] = '\0';

    return submit_signed_audit_entry(&entry);
}
